import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"Google Gemini (BYOK Provider)","description":"","frontmatter":{"title":"Google Gemini (BYOK Provider)"},"headers":[],"relativePath":"providers/gemini.md","filePath":"providers/gemini.md"}`),a={name:`providers/gemini.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="google-gemini-mode-byok" tabindex="-1">Google Gemini (Mode BYOK) <a class="header-anchor" href="#google-gemini-mode-byok" aria-label="Permalink to “Google Gemini (Mode BYOK)”">​</a></h1><p><strong>Google Gemini</strong> salah satu penyedia favorit untuk BYOK: ada <em>free tier</em> untuk mencoba tanpa kartu kredit, context window yang sangat panjang (hingga jutaan token di seri Flash/Pro terbaru), dan keluarga model yang beragam — mulai yang ringan untuk chat harian sampai yang bertenaga besar untuk <em>roleplay</em> raksasa. Kalau kamu baru mengenal BYOK, baca dulu <a href="./../byok/">Pengenalan BYOK</a>.</p><div class="warning custom-block"><p class="custom-block-title">📅 Info penting 2026</p><p>Kebijakan key dan harga Gemini berubah cukup sering di 2026. Halaman ini mengajarkan <strong>cara</strong> yang benar, bukan angka harga/limit tertentu. Selalu cek halaman resmi <a href="https://ai.google.dev/gemini-api/docs/pricing" target="_blank" rel="noreferrer">harga Gemini API</a> sebelum menetapkan budget.</p></div><hr><h2 id="membuat-api-key" tabindex="-1">Membuat API Key <a class="header-anchor" href="#membuat-api-key" aria-label="Permalink to “Membuat API Key”">​</a></h2><ol><li>Buka <a href="https://ai.google.dev/aistudio" target="_blank" rel="noreferrer">Google AI Studio</a> atau langsung ke <a href="https://aistudio.google.com/app/apikey" target="_blank" rel="noreferrer">halaman API key</a>.</li><li>Sign in dengan akun Google kamu.</li><li>Klik <strong>Create API key</strong> lalu ikuti langkahnya.</li></ol><div class="danger custom-block"><p class="custom-block-title">🔒 Wajib: restrict key ke Gemini API</p><p>Sejak pertengahan 2026, Gemini API <strong>menolak standard key yang <em>unrestricted</em></strong>. Saat membuat key, pastikan kamu membatasinya ke Gemini API saja — AI Studio menawarkan tombol <strong>&quot;Restrict key&quot;</strong> / <strong>&quot;Restrict to Gemini API only&quot;</strong> saat pembuatan. Key lama yang <em>unrestricted</em> dan terbengkalai bisa berstatus <strong>Blocked</strong>, jadi aplikasi akan error 403/401 padahal key kamu sebenarnya &quot;benar&quot;.</p></div><div class="tip custom-block"><p class="custom-block-title">🔐 Soal tipe &quot;auth keys&quot;</p><p>Key baru yang dibuat di AI Studio (setelah 28 Mei 2026) otomatis berupa <strong>auth keys</strong> — terikat ke <em>service account</em>, dengan batasan keamanan lebih ketat dan penegakan cepat untuk key yang bocor. Ini terjadi otomatis; kamu tidak perlu mengatur apa pun, cukup tahu bahwa bentuk key-nya memang sedikit berbeda dari dulu.</p></div><hr><h2 id="mengaktifkan-gemini-di-mikazuki-ai" tabindex="-1">Mengaktifkan Gemini di Mikazuki AI <a class="header-anchor" href="#mengaktifkan-gemini-di-mikazuki-ai" aria-label="Permalink to “Mengaktifkan Gemini di Mikazuki AI”">​</a></h2><p>Ikuti alur BYOK standar dari panduan <a href="./../byok/instalasi.html">Instalasi &amp; Aktivasi</a>. Ringkasannya untuk Gemini:</p><ol><li>Buka <strong>Settings → Engine</strong>, pilih mode <strong>BYOK</strong>.</li><li>Pada pilih provider, pilih <strong>Google Gemini</strong> (bukan entri yang menuntut <em>Base URL</em> manual).</li><li>Tempel API key yang barusan kamu buat.</li><li>Klik tombol 🔍 <strong>fetch models</strong> — daftar model akan muncul otomatis berdasarkan key kamu (misal versi Flash, Flash-Lite, atau seri lain yang aktif saat itu).</li><li>Pilih model, lalu atur <a href="./../byok/parameter-dasar.html">Parameter Dasar</a> — terutama <code>context_window</code> — dan klik simpan.</li></ol><div class="tip custom-block"><p class="custom-block-title">Sudah baik dari sananya</p><p>Default <strong>temperature 0.85</strong> Mikazuki sudah dipetakan dengan baik untuk roleplay; kamu tidak perlu mengubahnya kecuali memang ingin gaya jawaban yang sangat berbeda.</p></div><hr><h2 id="context-window-preset-1m" tabindex="-1">Context Window &amp; Preset 1M <a class="header-anchor" href="#context-window-preset-1m" aria-label="Permalink to “Context Window &amp; Preset 1M”">​</a></h2><p>Gemini punya context window yang terkenal luas — di seri Flash/Pro terbaru bisa mencapai jutaan token. Ini sangat cocok dengan preset <code>1M</code> di Mikazuki:</p><ul><li><strong>Model Flash/Flash-Lite terbaru</strong> → preset <code>1M</code> realistis untuk <em>roleplay</em> super panjang.</li><li><strong>Model lama atau tier tertentu</strong> kapasitasnya bisa lebih kecil — kalau ragu, mulai dari <code>128K</code>.</li></ul><p>Detail cara kerja <code>context_window</code>, <em>Reserved Output</em>, dan preset chip ada di <a href="./../byok/parameter-dasar.html">Parameter Dasar</a>.</p><div class="tip custom-block"><p class="custom-block-title">💡 Optimalkan 1M</p><p>Saat memakai preset <code>1M</code> di Gemini, kamu bisa menaikkan <code>max_tokens</code> agar jawaban punya ruang lebih besar — ingat bahwa <code>max_tokens</code> ikut dipotong dari context window.</p></div><hr><h2 id="free-tier-limit-harga" tabindex="-1">Free Tier, Limit &amp; Harga <a class="header-anchor" href="#free-tier-limit-harga" aria-label="Permalink to “Free Tier, Limit &amp; Harga”">​</a></h2><p>Aturan mainnya (berlaku umum, angka tidak kami kunci di sini):</p><ul><li><strong>Rate limit dihitung per Google Cloud project</strong>, bukan per key: ada batas RPM, TPM, dan RPD. Kuota harian reset pada tengah malam waktu Pasifik.</li><li><strong>Tier naik otomatis</strong> seiring pengeluaran (tier berikutnya terbuka setelah mencapai ambang <em>spend</em> tertentu). Semakin tinggi tier, semakin longgar limitnya.</li><li><strong>Selalu ada free tier</strong>, tapi sepanjang 2026 ia berkali-kali diperketat — model termahal (Pro) biasanya sudah tidak ikut gratis. Untuk gratisan, pakai model <strong>Flash</strong> atau <strong>Flash-Lite</strong>.</li><li><strong>Harga bisa berubah</strong>: ada promo harga untuk beberapa tier hingga akhir 2026 (dengan kenaikan menyusul di 2027), jadi jangan menetapkan budget berdasarkan angka yang dibaca sekali saja.</li></ul><div class="warning custom-block"><p class="custom-block-title">⚠️ Jangan kunci angka</p><p>Kami sengaja tidak mencantumkan tabel harga/RPM di halaman ini — angkanya cepat basi. Cek <a href="https://ai.google.dev/gemini-api/docs/pricing" target="_blank" rel="noreferrer">tabel harga resmi</a> dan dokumentasi <a href="https://ai.google.dev/gemini-api/docs/rate-limits" target="_blank" rel="noreferrer">rate limit</a> untuk angka terkini. Aturan praktis yang aman: model <strong>Flash/Flash-Lite</strong> untuk free tier, <strong>Pro</strong> untuk akun berbayar. Disarankan juga memasang <strong>billing alert</strong> di Google Cloud agar tagihan tidak mengejutkanmu.</p></div><hr><h2 id="opsi-cadangan-openai-compatible" tabindex="-1">Opsi Cadangan: OpenAI Compatible <a class="header-anchor" href="#opsi-cadangan-openai-compatible" aria-label="Permalink to “Opsi Cadangan: OpenAI Compatible”">​</a></h2><p>Kalau provider native <strong>Google Gemini</strong> di Mikazuki bermasalah (mis. pembaruan worker belum mendukung), Gemini punya endpoint <em>OpenAI-compatible</em> yang bisa dipakai lewat provider <strong>OpenAI Compatible</strong>:</p><ul><li><strong>Base URL</strong>: <code>https://generativelanguage.googleapis.com/v1beta/openai/</code></li><li><strong>API key</strong>: key Gemini kamu (endpoint OpenAI-nya menerima <em>Bearer key</em>).</li></ul><p>Ini jalur cadangan, bukan jalur utama — untuk penggunaan sehari-hari tetap pilih provider <strong>Google Gemini</strong> seperti di atas.</p><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h2><details class="details custom-block"><summary>Error 403 / 401 padahal key sudah benar</summary><p>Hampir selalu karena key <strong>unrestricted</strong> atau berstatus <strong>Blocked</strong>. Buka <a href="https://aistudio.google.com/app/apikey" target="_blank" rel="noreferrer">halaman API key</a> di AI Studio, cek label <em>&quot;Unrestricted&quot;</em> pada key kamu, lalu <strong>apply restriction</strong> ke Gemini API saja. Key lama yang terlanjur di-<em>block</em> perlu dibuat ulang dengan pembatasan yang benar.</p></details><details class="details custom-block"><summary>Error 429 — terlalu sering</summary><p>Rate limit Gemini dihitung <strong>per project</strong> (RPM/TPM/RPD), bukan per key, dan kuota harian reset pada tengah malam waktu Pasifik. Kalau kena, tunggu reset atau naikkan tier lewat pengeluaran model berbayar. Untuk free tier, gunakan model Flash/Flash-Lite — limitnya lebih ramah.</p></details><details class="details custom-block"><summary>Model tidak muncul di daftar setelah fetch</summary><p>Periksa tiga hal: key kamu valid tapi project-nya belum mengaktifkan Gemini API (service yang belum aktif biasanya kosong daftarnya), key dibatasi (restrict) salah selain ke service Gemini API, atau key salah tempel / terpotong. Retry tombol 🔍 fetch setelah memastikan ketiganya.</p></details><details class="details custom-block"><summary>Jawaban terpotong / berhenti di tengah</summary><p>Kemungkinan <code>max_tokens</code> di <a href="./../byok/parameter-dasar.html">Parameter Dasar</a> terlalu kecil. Naikkan nilainya — tapi ingat, <code>max_tokens</code> juga dipotong dari context window sebagai <em>Reserved Output</em>, jadi jangan set berlebihan tanpa menaikkan <code>context_window</code>.</p></details><details class="details custom-block"><summary>Harga di akhir bulan membesar</summary><p>Cek pengeluaran di konsol Google Cloud dan pastikan <strong>billing alert</strong> aktif. Promosi harga bisa berakhir (ada perubahan tarif yang dijadwalkan mulai 2027), jadi tinjau ulang <a href="https://ai.google.dev/gemini-api/docs/pricing" target="_blank" rel="noreferrer">tabel harga</a> secara berkala.</p></details><hr><h2 id="jelajahi-byok-lebih-lanjut" tabindex="-1">Jelajahi BYOK Lebih Lanjut <a class="header-anchor" href="#jelajahi-byok-lebih-lanjut" aria-label="Permalink to “Jelajahi BYOK Lebih Lanjut”">​</a></h2><ul><li><a href="./../byok/">Pengenalan BYOK</a> — cara kerja dan konsep dasarnya.</li><li><a href="./../byok/instalasi.html">Instalasi &amp; Aktivasi</a> — langkah menyalakan mode BYOK.</li><li><a href="./../byok/parameter-dasar.html">Parameter Dasar</a> — <code>max_tokens</code>, <code>context_window</code>, dan parameter kreativitas.</li></ul>`,39)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};